      "description": "Low limit alarm value"
    },
    {
      "direction": "INPUT",
      "name": "hystWindow",
      "type": "REAL",
      "description": "Hysteresis window"
    },
    {
      "direction": "OUTPUT",
      "name": "hiAlarm",
      "type": "BOOL",
      "description": "High limit alarm"
    },
    {
      "direction": "OUTPUT",
      "name": "loAlarm",
      "type": "BOOL",
      "description": "Low limit alarm"
    },
    {
      "direction": "OUTPUT",
