      "id": "A4_highTrigger",
      "formula": "G(((loLevel < hiLevel) & (hystWindow < real32(hiLevel - loLevel)) & (hystWindow >= 0.0) & (Value > hiLevel)) -> hiAlarm)"
    },
    {
      "id": "A5_highRelease",
      "formula": "G(((loLevel < hiLevel) & (hystWindow < real32(hiLevel - loLevel)) & (hystWindow >= 0.0) & (Value < real32(hiLevel - hystWindow))) -> !hiAlarm)"
    },
    {
      "id": "A6_highHysteresisRetain",
      "formula": "G(((loLevel < hiLevel) & (hystWindow < real32(hiLevel - loLevel)) & (hystWindow >= 0.0) & (real32(hiLevel - hystWindow) <= Value) & (Value <= hiLevel)) -> (hiAlarm = Y(hiAlarm)))"
    },
    {
      "id": "A7_lowTrigger",
      "formula": "G(((loLevel < hiLevel) & (hystWindow < real32(hiLevel - loLevel)) & (hystWindow >= 0.0) & (Value < loLevel)) -> loAlarm)"
    },
    {
      "id": "A8_lowRelease",
      "formula": "G(((loLevel < hiLevel) & (hystWindow < real32(hiLevel - loLevel)) & (hystWindow >= 0.0) & (Value > real32(loLevel + hystWindow))) -> !loAlarm)"
